const {test}=require('node:test');
const assert=require('node:assert/strict');
const L=require('../calendar.js'),H=require('../hours.js'),R=require('../roman-office.js');
const us={epiphany:'sunday',ascension:'sunday',corpus:'sunday'};
const date=s=>new Date(s+'T00:00:00Z');

// USCCB 2027cal.pdf, printed pp. 11–31. These are independent published
// Psalter-week anchors, not values generated by Ora's calendar algorithm.
test('published seasonal Psalter anchors through June 2027',()=>{
  const anchors={
    '2026-11-29':1,'2026-12-06':2,'2026-12-13':3,'2026-12-20':4,
    '2027-01-02':1,'2027-01-04':2,'2027-01-08':2,'2027-01-09':2,
    '2027-01-11':1,'2027-01-17':2,'2027-01-24':3,'2027-01-31':4,
    '2027-02-07':1,'2027-02-10':4,'2027-02-14':1,'2027-02-21':2,
    '2027-02-28':3,'2027-03-07':4,'2027-03-14':1,'2027-03-21':2,
    '2027-04-04':2,'2027-04-11':3,'2027-04-18':4,'2027-04-25':1,
    '2027-05-02':2,'2027-05-17':3,'2027-05-24':4,
    '2027-06-01':1,'2027-06-06':2,'2027-06-13':3,'2027-06-20':4,'2027-06-27':1
  };
  for(const [iso,week]of Object.entries(anchors))assert.equal(H.psalterWeek(L,date(iso),us),week,iso);
});

test('Evening Prayer and Compline share precedence and the selected transfer settings',()=>{
  // GILH 204–205, 225, 230–233; Universal Norms 61.
  const cases=[
    ['2026-11-28',true,6,/Advent/],
    ['2026-12-07',true,6,/Immaculate Conception/],
    ['2026-12-08',false,0,/Immaculate Conception/],
    ['2026-12-26',true,6,/Holy Family/],
    ['2027-01-02',true,6,/Epiphany/],
    ['2027-01-09',true,6,/Baptism/],
    ['2027-02-01',false,1,/Week/], // weekday Presentation has no First Vespers
    ['2027-03-18',true,6,/Joseph/],
    ['2027-03-27',false,6,/Holy Saturday/], // no anticipation of Easter Vespers
    ['2027-04-03',true,6,/Second Sunday of Easter/],
    ['2027-04-04',false,0,/Second Sunday of Easter/], // Sunday outranks transferred Annunciation
    ['2027-06-03',true,6,/Sacred Heart/],
    ['2027-06-28',true,6,/Peter and Paul/]
  ];
  for(const [iso,first,index,title]of cases){
    const e=R.evening(L,date(iso),us),n=H.romanNightPlan(L,date(iso),us);
    assert.equal(e.first,first,iso);assert.equal(n.index,index,iso);
    assert.match(e.observance.title,title,iso);assert.equal(n.observance,e.observance.title,iso);
  }
  assert.equal(R.evening(L,date('2027-05-05'),{...us,ascension:'thursday'}).first,true);
  assert.equal(R.evening(L,date('2027-05-05'),us).first,false);
  assert.equal(H.romanNightPlan(L,date('2027-05-06'),{...us,ascension:'thursday'}).index,0);
  assert.equal(H.romanNightPlan(L,date('2027-05-06'),us).index,4);
  assert.equal(H.modernPsalmody(L,date('2027-05-06'),'L',{...us,ascension:'thursday'}).festiveMorning,true);
  assert.equal(H.modernPsalmody(L,date('2027-05-06'),'L',us).festiveMorning,false);
});

test('rendered verses respect omitted verses, embedded boundaries and half-verse divisions',()=>{
  const rows=H.modernPsalm('142(1-11)')[0].rows;
  assert.ok(rows.some(r=>r[0]===4));assert.ok(rows.some(r=>r[0]===10&&r[1]==='a'));
  assert.ok(rows.every(r=>r[0]<=11));
  assert.doesNotMatch(rows.map(r=>r[2]).join(' '),/destroy my enemies|cut off all/);
  const wed=H.modernPsalm('30(2-6)')[0].rows;
  assert.ok(wed.every(r=>r[0]>=2&&r[0]<=6));assert.match(wed.at(-1)[2],/Into thy hands/);
  const first=H.modernPsalm('144(1-13a)')[0].rows,second=H.modernPsalm('144(13b-21)')[0].rows;
  assert.doesNotMatch(first.map(r=>r[2]).join(' '),/faithful in all his words/);
  assert.match(second[0][2],/faithful in all his words/);
});

test('Sunday Daniel canticles render fully and Holy Saturday has proper Lauds',()=>{
  for(const iso of ['2027-01-17','2027-01-31']){
    const html=H.modern(L,date(iso),'L',us);
    assert.match(html,/Blessed art thou in the holy temple/);
    assert.match(html,/All ye works of the Lord, bless the Lord/);
  }
  const holySaturday=H.modernPsalmody(L,date('2027-03-27'),'L',us);
  assert.equal(holySaturday.items[0],'p63');assert.match(holySaturday.items[1],/Isaiah 38/);
  assert.equal(holySaturday.items[2],'p150');
  // The modern view drops chant/rubric marks while the historical source survives.
  const html=H.modern(L,date('2026-11-29'),'L',us);
  assert.doesNotMatch(html,/Bow head|of_the_Blessed/);
  assert.match(H.H.ps['210'].map(r=>r[2]).join(' '),/Bow head/);
});

test('every target day renders all three plans with First Edition provenance',()=>{
  for(let d=date('2026-11-12');d<=date('2027-06-30');d=L.add(d,1)){
    for(const which of ['L','V']){
      const plan=H.modernPsalmody(L,d,which,us);
      assert.equal(plan.items.length,3,L.iso(d));
      for(const ref of plan.items)if(/^[pc]/.test(ref))assert.ok(H.modernPsalm(ref.slice(1))[0]?.rows.length,`${L.iso(d)} ${ref}`);
      assert.doesNotMatch(H.modern(L,d,which,us),/undefined|NaN/);
      assert.equal(plan.reference.edition,'first');
      assert.equal(plan.reference.authorizedStructuredSource,null);
    }
    assert.ok(H.romanNightPlan(L,d,us).index>=0);
  }
});

test('seasonal hymns follow modern Lent and Pentecost boundaries',()=>{
  const ash=H.modern(L,date('2027-02-10'),'L',us);
  assert.ok(ash.includes(H.H.seas.Quad.L.split('\n')[0]));
  const afterPentecost=H.modern(L,date('2027-05-18'),'L',us);
  assert.ok(!afterPentecost.includes(H.H.seas.Pasch.L.split('\n')[0]));
});

test('Agnes retains her proper morning psalmody without generalizing to other memorials',()=>{
  const agnes=H.modernPsalmody(L,date('2027-01-21'),'L',us);
  assert.deepEqual(agnes.items,['p62(2-9)','c210','p149']);
  assert.equal(L.roman(date('2027-01-21'),us).rank,'Memorial');
  const josaphat=H.modernPsalmody(L,date('2026-11-12'),'L',us);
  assert.equal(josaphat.items[0],'p142(1-11)');
});

test('Easter octave and its closing Sunday retain proper Lauds and Vespers psalmody',()=>{
  for(let d=date('2027-03-28');d<=date('2027-04-04');d=L.add(d,1)){
    assert.deepEqual(H.modernPsalmody(L,d,'L',us).items,['p62(2-9)','c210','p149'],L.iso(d));
    const evening=H.modernPsalmody(L,d,'V',us).items;
    assert.deepEqual(evening.slice(0,2),['p109(1-5,7)','p113(1-8)'],L.iso(d));
    assert.match(evening[2],/Revelation 19:1-7/);
  }
  assert.notDeepEqual(H.modernPsalmody(L,date('2027-04-06'),'V',us).items.slice(0,2),['p109(1-5,7)','p113(1-8)']);
});
